[{"order":1,"type":"heading","text":"Mastering Test Repetition and Timeout Management in JUnit 5"},{"order":2,"type":"paragraph","text":"Writing robust tests often requires validating behavior under repeated conditions or ensuring execution finishes within strict time boundaries. JUnit 5 provides built-in annotations like @RepeatedTest and @Timeout to address these advanced testing requirements seamlessly."},{"order":3,"type":"subheading","text":"Using @RepeatedTest for Flaky or Randomized Tests"},{"order":4,"type":"paragraph","text":"The @RepeatedTest annotation is used to signal that the annotated method is a test template that should be executed multiple times. You can specify the total number of repetitions directly in the annotation."},{"order":5,"type":"code","text":"import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.TestInfo;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class RepeatedTestsDemo {

    @RepeatedTest(5)
    void testComputation(TestInfo testInfo) {
        boolean result = Math.random() < 0.9;
        assertTrue(result, "Computation failed on repetition");
    }
}"},{"order":6,"type":"subheading","text":"Accessing Repetition Metadata"},{"order":7,"type":"paragraph","text":"When executing repeated tests, you often need to know the current repetition number or the total number of invocations. JUnit allows you to inject RepetitionInfo into your test method constructor or parameters."},{"order":8,"type":"code","text":"import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.RepetitionInfo;

public class MetadataDemo {

    @RepeatedTest(value = 3, name = "{displayName} - repetition {currentRepetition} of {totalRepetitions}")
    void customNameTest(RepetitionInfo repetitionInfo) {
        System.out.println("Executing repetition: " + repetitionInfo.getCurrentRepetition());
    }
}"},{"order":9,"type":"subheading","text":"Managing Execution Duration with @Timeout"},{"order":10,"type":"paragraph","text":"Performance and responsiveness are critical software metrics. The @Timeout annotation fails a test if its execution takes longer than a specified duration. It can be applied to individual test methods, lifecycle methods, or entire test classes."},{"order":11,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import java.util.concurrent.TimeUnit;

public class TimeoutDemo {

    @Test
    @Timeout(value = 500, unit = TimeUnit.MILLISECONDS)
    void quickTask() throws InterruptedException {
        Thread.sleep(100);
    }
}"},{"order":12,"type":"subheading","text":"Combining @RepeatedTest and @Timeout"},{"order":13,"type":"paragraph","text":"You can combine both features to ensure that every single repetition of a performance-sensitive test completes within the allotted time limit."},{"order":14,"type":"code","text":"import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Timeout;

public class CombinedDemo {

    @RepeatedTest(10)
    @Timeout(1)
    void repeatedPerformanceTest() {
        // Each of the 10 repetitions must finish within 1 second
    }
}"},{"order":15,"type":"subheading","text":"Best Practices"},{"order":16,"type":"bullet_point","text":"Use @RepeatedTest primarily for stress testing, verifying randomized algorithms, or exposing intermittent concurrency issues."},{"order":17,"type":"bullet_point","text":"Configure sensible timeout thresholds that account for CI/CD environment variations and resource constraints."},{"order":18,"type":"bullet_point","text":"Leverage custom display names in @RepeatedTest to easily identify failing iterations in test reports."}]
